import Link from 'next/link';

export default function Register() {
  return (
    <main>
      <h1>Inscription</h1>
      <form>
        <div>
          <label>Nom:</label>
          <input type="text" />
        </div>
        <div>
          <label>Email:</label>
          <input type="email" />
        </div>
        <div>
          <label>Mot de passe:</label>
          <input type="password" />
        </div>
        <button type="submit">S'inscrire</button>
      </form>
      <Link href="/">Retour à l'accueil</Link>
    </main>
  );
}